import{_ as o,o as t,c as r,ae as d}from"./chunks/framework.BX6FPmO9.js";const p=JSON.parse('{"title":"專案規範（開發管控）","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/coding-conventions.md","filePath":"conventions/coding-conventions.md"}'),a={name:"conventions/coding-conventions.md"};function c(s,e,n,i,l,h){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="專案規範-開發管控" tabindex="-1">專案規範（開發管控） <a class="header-anchor" href="#專案規範-開發管控" aria-label="Permalink to &quot;專案規範（開發管控）&quot;">​</a></h1><p><strong>類型</strong>：spec | <strong>權重</strong>：1</p><p>本文件為 AI 輔助開發（Cursor 等）與人工協作時共同遵守的規範，包含命名、結構與檢查方式。</p><h2 id="檔案與資料夾命名" tabindex="-1">檔案與資料夾命名 <a class="header-anchor" href="#檔案與資料夾命名" aria-label="Permalink to &quot;檔案與資料夾命名&quot;">​</a></h2><h3 id="資料夾" tabindex="-1">資料夾 <a class="header-anchor" href="#資料夾" aria-label="Permalink to &quot;資料夾&quot;">​</a></h3><ul><li><strong>規則</strong>：僅使用<strong>小寫英文字母與數字</strong>，不使用連字號、底線或駝峰。</li><li><strong>範例</strong>：<code>chat</code>、<code>ui</code>、<code>lui</code>、<code>errorboundary</code>、<code>features</code>、<code>shared</code>。</li><li><strong>錯誤</strong>：<code>error-boundary</code>、<code>ErrorBoundary</code>、<code>chat_interface</code>。</li><li><strong>適用範圍</strong>：<code>app/</code> 下除 <code>app/routes</code> 外之所有資料夾（<code>app/routes</code> 依 Remix 慣例可含 <code>_</code>、<code>$</code> 等）。</li></ul><h3 id="元件檔-react-ui" tabindex="-1">元件檔（React / UI） <a class="header-anchor" href="#元件檔-react-ui" aria-label="Permalink to &quot;元件檔（React / UI）&quot;">​</a></h3><ul><li><strong>路徑</strong>：<code>app/components/**/*.tsx</code>。</li><li><strong>規則</strong>：檔名（不含副檔名）為 <strong>PascalCase</strong>。</li><li><strong>範例</strong>：<code>ChatInterface.tsx</code>、<code>ErrorBoundaryFallback.tsx</code>、<code>Button.tsx</code>。</li><li><strong>例外</strong>：<code>index.ts</code> / <code>index.tsx</code> 作為 barrel 可接受；co-located 測試 <code>ComponentName.test.tsx</code> / <code>ComponentName.spec.tsx</code>（base 名須 PascalCase）。</li></ul><h3 id="其他程式檔" tabindex="-1">其他程式檔 <a class="header-anchor" href="#其他程式檔" aria-label="Permalink to &quot;其他程式檔&quot;">​</a></h3><ul><li><strong>features / services / shared</strong>：可為小寫 + 點號（如 <code>dish.server.ts</code>、<code>dish.types.ts</code>）或小寫（如 <code>cn.ts</code>、<code>errors.ts</code>），與現有專案一致即可。</li><li><strong>routes</strong>：依 Remix 慣例（如 <code>_index.tsx</code>、<code>api.chat.ts</code>），不在此命名檢查範圍。</li></ul><h3 id="元件層-ui-vs-theme-骨架-vs-kit-表面" tabindex="-1">元件層：ui vs theme（骨架 vs kit 表面） <a class="header-anchor" href="#元件層-ui-vs-theme-骨架-vs-kit-表面" aria-label="Permalink to &quot;元件層：ui vs theme（骨架 vs kit 表面）&quot;">​</a></h3><ul><li><strong>Primitive 元件</strong>：一律放在 <code>app/components/ui/*</code>；不隨 UI kit 更換而搬動。</li><li><strong>與特定 UI kit 綁定的樣式或 wrapper</strong>：放在 <code>app/components/theme/*</code>（可隨 kit 替換）。</li><li><strong>禁止</strong>：在 <code>app/components/ui/*</code> 內依 kit 再分子目錄（例如不用 <code>ui/core/</code>、<code>ui/kit/</code>）；骨架保持單一 primitive 層。見 <a href="./../architecture/design-system.html#骨架-vs-視覺ui-kit">design-system 骨架 vs 視覺</a>。</li></ul><h3 id="簡表" tabindex="-1">簡表 <a class="header-anchor" href="#簡表" aria-label="Permalink to &quot;簡表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>類型</th><th>規則</th><th>範例</th></tr></thead><tbody><tr><td><code>app/**</code> 資料夾（非 routes）</td><td>資料夾</td><td>小寫、無分隔符</td><td><code>errorboundary</code></td></tr><tr><td><code>app/components/**</code></td><td><code>.tsx</code> 檔</td><td>PascalCase</td><td><code>ErrorBoundaryFallback.tsx</code></td></tr><tr><td><code>app/components/**</code></td><td>co-located test</td><td><code>ComponentName.test.tsx</code></td><td><code>AiFallbackPanel.test.tsx</code></td></tr><tr><td><code>app/components/**</code></td><td>barrel</td><td><code>index.ts</code></td><td><code>index.ts</code></td></tr></tbody></table><h2 id="檢查方式" tabindex="-1">檢查方式 <a class="header-anchor" href="#檢查方式" aria-label="Permalink to &quot;檢查方式&quot;">​</a></h2><ul><li><strong>ESLint</strong>：程式碼與 import 等由既有 ESLint 規則檢查。</li><li><strong>檔名 / 資料夾名</strong>：由 <code>pnpm run lint:filenames</code> 檢查，CI 與 pre-commit 會執行。</li><li>新增或重新命名檔案、資料夾後請執行 <code>pnpm run lint:filenames</code> 或透過 commit 觸發檢查。</li></ul><h2 id="ai-輔助開發-cursor-其他" tabindex="-1">AI 輔助開發（Cursor / 其他） <a class="header-anchor" href="#ai-輔助開發-cursor-其他" aria-label="Permalink to &quot;AI 輔助開發（Cursor / 其他）&quot;">​</a></h2><ul><li>建立新元件時：資料夾用<strong>小寫無分隔符</strong>，元件檔用 <strong>PascalCase</strong>。</li><li>勿使用 kebab-case（<code>error-boundary</code>）或 camelCase 資料夾（<code>errorBoundary</code>）作為元件目錄名。</li><li>其餘程式風格依 <code>.cursor/rules</code> 與 <a href="./../architecture/system-overview.html">architecture/system-overview</a>、<a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a>。</li></ul>',18)])])}const m=o(a,[["render",c]]);export{p as __pageData,m as default};
